import java.util.*;

class Solution {
    private int[][] isConnected;
    private boolean[] visited;
    private int n;

    public int findCircleNum(int[][] isConnected) {
        if (isConnected == null || isConnected.length == 0) return 0;
        this.isConnected = isConnected;
        this.n = isConnected.length;
        this.visited = new boolean[n];

        int count = 0;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                count++;
                dfs(i);
            }
        }
        return count;
    }

    private void dfs(int i) {
        visited[i] = true;
        for (int j = 0; j < n; j++) {
            if (isConnected[i][j] == 1 && !visited[j]) dfs(j);
        }
    }
}

import java.util.*;

class Solution {
    public int findCircleNum(int[][] isConnected) {
        if (isConnected == null || isConnected.length == 0) return 0;
        int n = isConnected.length;
        boolean[] visited = new boolean[n];
        Deque<Integer> queue = new ArrayDeque<>();
        int count = 0;

        for (int i = 0; i < n; i++) {
            if (visited[i]) continue;
            count++;
            visited[i] = true;
            queue.add(i);

            while (!queue.isEmpty()) {
                int u = queue.poll();
                for (int j = 0; j < n; j++) {
                    if (isConnected[u][j] == 1 && !visited[j]) {
                        visited[j] = true;
                        queue.add(j);
                    }
                }
            }
        }
        return count;
    }
}

import java.util.*;

class Solution {
    private int[] parent;

    public int findCircleNum(int[][] isConnected) {
        if (isConnected == null || isConnected.length == 0) return 0;
        int n = isConnected.length;
        parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        int count = n;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (isConnected[i][j] == 1) {
                    int ra = find(i);
                    int rb = find(j);
                    if (ra != rb) {
                        parent[ra] = rb;
                        count--;
                    }
                }
            }
        }
        return count;
    }

    private int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
}
